-- a frame can be empty: aggregates give their empty-input value, first/last/nth NULL
CREATE TABLE e (i INTEGER, w TEXT);
INSERT INTO e VALUES (1,'a'),(2,'b'),(3,'c'),(4,'d');
SELECT i, count(*) OVER (ORDER BY i ROWS BETWEEN 2 FOLLOWING AND 3 FOLLOWING), sum(i) OVER (ORDER BY i ROWS BETWEEN 2 FOLLOWING AND 3 FOLLOWING) FROM e ORDER BY i;
SELECT i, total(i) OVER (ORDER BY i ROWS BETWEEN 1 PRECEDING AND 2 PRECEDING), group_concat(w) OVER (ORDER BY i ROWS BETWEEN 1 PRECEDING AND 2 PRECEDING) FROM e ORDER BY i;
SELECT i, first_value(w) OVER (ORDER BY i ROWS BETWEEN 3 PRECEDING AND 2 PRECEDING), last_value(w) OVER (ORDER BY i ROWS BETWEEN 1 FOLLOWING AND 1 FOLLOWING) FROM e ORDER BY i;
SELECT i, avg(i) OVER (ORDER BY i RANGE BETWEEN 1 FOLLOWING AND 1 FOLLOWING), max(w) OVER (ORDER BY i RANGE BETWEEN 3 FOLLOWING AND 2 FOLLOWING) FROM e ORDER BY i;
